) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q967065', 'Djiboutian constitutional referendum, 1992', 'A constitutional referendum was held in Djibouti on 4 September 1992. The new constitution would restore multi-party democracy for the first time since independence.', 1992, 9, 4, NULL, NULL, NULL, 'day', '4 September 1992', 39, 'https://en.wikipedia.org/wiki/1992_Djiboutian_constitutional_referendum'),
